using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RepairWithEffectAction", menuName = "Data/Battle/Battle Actions/Hevelius/RepairWithEffect Action")]
public class RepairWithEffectAction : RepairAction
{
	[Header("RepairWithEffect Action")]
	[SerializeField]
	private Effect effect;

	[SerializeField]
	private bool blast;

	public Effect Effect => effect;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		GameObject aliveCompanion = GetAliveCompanion(target);
		bool wasBoosted = aliveCompanion.GetComponent<CompanionEffects>().WasBoosted;
		InitializeCompanion(target, initializeCompanionEntirely: true);
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
		{
			UnitEffects component = target.transform.parent.parent.GetFirstChild().GetComponent<UnitEffects>();
			component.AddEffect(effect, amount);
			if (!blast)
			{
				component.IsEffectActiveWithActivation(effect);
			}
			List<bool> boostedList = new List<bool>();
			boostedList.Add(wasBoosted);
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
			{
				List<GameObject> targets = new List<GameObject> { aliveCompanion };
				SpawnCompanionDice(targets, recycle: false, source, boostedList);
				SpawnVFX(GetVFXOwnerPosition(target), 5f);
			});
		});
	}
}
